@startuml

class GameDesigner {}

class Player {}

class BoardGame {}

class Board {}

class Tile {}

class ConnectionPiece {}

class ActionCard {}

class PlayingPiece {}

class Die {}

enum ActionType {
  ExtraTurn
  ConnectTiles
  RemoveConnection
  MoveToArbitraryTile
  LoseTurn
}

enum TileColor {
  White
  Black
}

enum Side {
  Top
  Bottom
  Left
  Right
}

GameDesigner "1" -- "*" BoardGame : designs
BoardGame "1" -- "1" Board : has
BoardGame "1" -- "1" Die : uses
BoardGame "1" -- "1" ActionCard : contains
BoardGame "1" -- "2..4" Player : involves

Board "1" *-- "*" Tile : consists of
Board "1" *-- "*" ConnectionPiece : consists of

Tile "1" -- "0..1" Tile : connects to (top)
Tile "1" -- "0..1" Tile : connects to (bottom)
Tile "1" -- "0..1" Tile : connects to (left)
Tile "1" -- "0..1" Tile : connects to (right)

Tile "1" -- "0..1" Tile : is_hidden_tile
Tile "0..1" -- "1" ActionCard : is_action_tile

Player "1" -- "1" PlayingPiece : has
PlayingPiece "1" -- "1" Tile : is_on

@enduml

